Let $V$ be a finite relational vocabulary and $\mathcal{M}$ a $V$-structure. We call $\mathcal{M}$ {\em homogeneous}
if for all finite substructures $\mathcal{A}$ and $\mathcal{B}$ of $\mathcal{M}$, every isomorphism from $\mathcal{A}$ to $\mathcal{B}$ can be extended to an
automorphism of $\mathcal{M}$.\\
(ii) We say that a structure $\mathcal{M}$, with any vocabulary, is {\em $\omega$-homogeneous} 
if whenever $n < \omega$,
$a_1, \ldots, a_n, a_{n+1}, b_1, \ldots, b_n \in M$ and $\mathrm{tp}_\mathcal{M}(a_1, \ldots, a_n) = \mathrm{tp}_\mathcal{M}(b_1, \ldots, b_n)$,
then there is $b_{n+1} \in M$ such that $\mathrm{tp}_\mathcal{M}(a_1, \ldots, a_{n+1}) = \mathrm{tp}_\mathcal{M}(b_1, \ldots, b_{n+1})$.
}\end{defin}

We say that  $T$ has {\em trivial dependence} if, whenever $\mathcal{M} \models T$,
$A, B, C_1, C_2 \subseteq M^{\mathrm{eq}}$ and $A \underset{B}{\raisebox{-2pt}[5pt][0pt]{$\smile$} 
\hspace*{-6.8pt}\raisebox{3pt}[5pt][0pt]{$|$}\hspace*{-6.8pt}
\raisebox{3pt}[5pt][0pt]{$\diagup$} } (C_1 \cup C_2)$, 
then $A \underset{B}{\raisebox{-2pt}[5pt][0pt]{$\smile$} 
\hspace*{-6.8pt}\raisebox{3pt}[5pt][0pt]{$|$}\hspace*{-6.8pt}
\raisebox{3pt}[5pt][0pt]{$\diagup$} } C_i$ for $i = 1$ or $i = 2$.\\
(ii) $T$ (as well as every model of it) is {\em 1-based} if for every $\mathcal{M} \models T$ and all $A, B \subseteq M^{\mathrm{eq}}$, 
$A$ is independent from $B$ over $\mathrm{acl}_{\mathcal{M}^{\mathrm{eq}}}(A) \cap \mathrm{acl}_{\mathcal{M}^{\mathrm{eq}}}(B)$.
}\end{defin}

A finite $V$-structure $\mathcal{A}$ is called a {\em forbidden structure with respect to $\mathcal{M}$}
if $\mathcal{A}$ cannot be embedded into $\mathcal{M}$.\\
(ii) Suppose that $\mathcal{A}$ is a forbidden structure with respect to $\mathcal{M}$.
We call $\mathcal{A}$ a {\em minimal} forbidden structure with respect to $\mathcal{M}$ if 
no proper substructure of $\mathcal{A}$ is a forbidden structure with respect to $\mathcal{M}$.\\
(iii) We call {\em $\mathcal{M}$ a binary random structure} if there does {\em not} exist a minimal forbidden structure $\mathcal{A}$ with
respect to $\mathcal{M}$ such that $|A| \geq 3$.
}\end{defin}

We say that $\mathcal{N}$ is {\em strongly interpretable in $\mathcal{M}$} if there are
\begin{itemize}
\item $0 < n < \omega$, 
\item a formula $\chi(x_1, \ldots, x_n)$ without parameters in the language of $\mathcal{M}$,
\item a bijective function $f : \chi(\mathcal{M}) \to N$, and
\item for every $0 < k < \omega$ and formula $\varphi(x_1, \ldots, x_k)$ without parameters in the language of $\mathcal{N}$,
a formula $\psi_\varphi(\bar{y}_1, \ldots, \bar{y}_k)$ without parameters in the language of $\mathcal{M}$,
such that, for all $\bar{a}_1, \ldots, \bar{a}_k \in \chi(\mathcal{M})$, 
\[ \mathcal{M} \models \psi_\varphi(\bar{a}_1, \ldots, \bar{a}_k) \ \Longleftrightarrow \ \mathcal{N} \models \varphi(f(\bar{a}_1), \ldots, f(\bar{a}_k)).\]
\end{itemize}
(ii) We say that $\mathcal{N}$ is {\em definable in $\mathcal{M}$} if $\mathcal{N}$ is strongly interpretable in $\mathcal{M}$ and it is possible to
choose $n = 1$ in the definition of `strongly interpretable'.
}\end{defin}

\label{properties of binary random structures}
Let $\mathcal{M}$ be a binary random structure.
Then $Th(\mathcal{M})$ is simple, has $\mathrm{SU}$-rank 1 and is 1-based with trivial dependence.

It follows from the definition of having height 1 (Definition~\ref{definition of height}) and 
Lemmas~\ref{height and existence of a coordinatizing rank one set}
and~\ref{r=1} that in either case we have $r=1$.

If $m > 2$, then, by using that $\mathcal{R}$ is a random structure again, we find 
{\em distinct} elements $b'_3, \ldots, b'_m, b''_3, \ldots, b''_m \in R$ such that if we let
\begin{equation}\label{identifications of elements}
b'_1 = b_1, \ b''_1 = b_2, \ b''_2 = b'_2,
\end{equation}
then
\begin{align}\label{the other sequences have the same type}
\mathrm{tp}_\mathcal{R}(b_1, b_2, \ldots, b_m) \ = \ 
\mathrm{tp}_\mathcal{R}(b'_1, b'_2, \ldots, b'_m) \ = \ 
\mathrm{tp}_\mathcal{R}(b''_1, b''_2, \ldots, b''_m).

\begin{equation}\label{all element have the same acl in C_r-1}
\text{ for all } b \in M, \ \mathrm{acl}(b) \cap C_{r-1} = \mathrm{acl}(a) \cap C_{r-1}.
\end{equation}

\begin{equation}\label{a is in definable closure of acl(a) cut with R}
\text{for every $a \in M$, $a \in \mathrm{dcl}_{\mathcal{R}^{\mathrm{eq}}}(\mathrm{crd}(a))$.}
\end{equation}

\begin{align*}
&\mathrm{tp}(a, a'') = \mathrm{tp}(a, a^*) \text{ and } \mathrm{tp}(a', a'') = \mathrm{tp}(a', a^*), \text{ and hence} \\
&\mathrm{tp}_\mathcal{M}(a, a'') = \mathrm{tp}_\mathcal{M}(a, a^*) \text{ and } \mathrm{tp}_\mathcal{M}(a', a'') = \mathrm{tp}_\mathcal{M}(a', a^*).
\end{align*}

\begin{align}\label{the long sequences have the same type}
&\mathrm{tp}(b_1, \ldots, b_m, b'_1, \ldots, b'_m, b''_1, \ldots, b''_m) \\ 
= \ 
