\end{equation}

\begin{align}\label{the other sequences have the same type}
\mathrm{tp}_\mathcal{R}(b_1, b_2, \ldots, b_m) \ = \ 
\mathrm{tp}_\mathcal{R}(b'_1, b'_2, \ldots, b'_m) \ = \ 
\mathrm{tp}_\mathcal{R}(b''_1, b''_2, \ldots, b''_m). 
\end{align}

\begin{align}\label{the same type when the other sequences are permuted}
\mathrm{tp}_\mathcal{R}(b_1, b_2, \ldots, b_m) \ &= \ \mathrm{tp}_\mathcal{R}(b_{\pi(1)}, b_{\pi(2)}, \ldots, b_{\pi(m)}),  \\
\mathrm{tp}_\mathcal{R}(b'_1, b'_2, \ldots, b'_m) \ &= \ \mathrm{tp}_\mathcal{R}(b'_{\pi(1)}, b'_{\pi(2)}, \ldots, b'_{\pi(m)}) \quad \text{ and} \nonumber \\
\mathrm{tp}_\mathcal{R}(b''_1, b''_2, \ldots, b''_m) \ &= \ \mathrm{tp}_\mathcal{R}(b''_{\pi(1)}, b''_{\pi(2)}, \ldots, b''_{\pi(m)}), \nonumber
\end{align}

\begin{align}\label{equal types of some long sequences}
\mathrm{tp}_\mathcal{R}(b_1, \ldots, b_m,  c_1, \ldots, c_m)  \ &= \ \mathrm{tp}_\mathcal{R}(b_{\pi(1)}, \ldots, b_{\pi(m)},  b''_1, \ldots, b''_m)
\quad \text{ and} \\
