\nonumber
\end{align}

\begin{equation}\label{C_1 is a trivial geometry}
\text{ for every } A \subseteq C_1, \ \mathrm{acl}(A) \cap C_1 = A.
\end{equation}

\begin{equation}\label{every member of C_1 is a coordinate of M}
\text{ for every $c \in C_1$, there is $a \in M$ such that $c \in \mathrm{crd}(a)$.}
